/// Look up a parameter point by its short name.
pub fn by_name(name: &str) -> Option<&'static ParamSet> {
    let mut i = 0;
    while i < ALL.len() {
        if str_eq(ALL[i].name, name) {
            return Some(ALL[i]);
        }
        i += 1;
    }
    None
}

fn str_eq(a: &str, b: &str) -> bool {
    a.as_bytes() == b.as_bytes()
}
